using System;using System.IO;using System.Linq;using System.Collections;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using NarutoVR.QingGuiR03Review;using Object=UnityEngine.Object;
[InitializeOnLoad] public static class QingGuiR03CasterBiasCheck {
 const string Key="QingGuiR03CasterBiasCheck.Run";const string Out=QingGuiR03FirstLook.Logs+"/caster-bias-01";static IEnumerator routine;static int frame;static Camera cam;static GameObject item;static Renderer[] parts;static Renderer core;static RenderTexture target;static Texture2D pixels;
 static QingGuiR03CasterBiasCheck()=>EditorApplication.update+=Boot;
 public static void Run(){Directory.CreateDirectory(Out);EditorSceneManager.OpenScene(QingGuiR03FirstLook.Root+"/QingGuiR03_FirstLook.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
 static void Boot(){if(!Application.isPlaying||EditorApplication.isCompiling||!SessionState.GetBool(Key,false))return;SessionState.SetBool(Key,false);try{cam=Camera.main;cam.enabled=true;item=GameObject.Find("R03 Actual three-part object");parts=item.GetComponentsInChildren<Renderer>();core=parts.Single(r=>r.name.Contains("JadeCore"));foreach(var r in parts){var m=new Material(r.sharedMaterial);if(r.name.Contains("BronzeFrame")){m.shader=AssetDatabase.LoadAssetAtPath<Shader>(QingGuiR03FirstLook.Root+"/Shaders/QingGuiR03GoldLit.shader");m.SetFloat("_SpecularAAStrength",0);m.SetFloat("_ClearCoatMask",0);}else m.SetFloat("_SpecularAAStrength",1);m.SetFloat("_TransmissionDebug",0);m.SetVector("_CasterBiasLimit",Vector4.zero);r.sharedMaterial=m;}target=new RenderTexture(1280,960,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear){antiAliasing=4};target.Create();pixels=new Texture2D(1280,960,TextureFormat.RGBA32,false,true);QualitySettings.realtimeReflectionProbes=true;new GameObject("R03 bias tick").AddComponent<QingGuiR03ReviewTick>();QingGuiR03ReviewTick.Tick=Step;routine=Check();}catch(Exception e){Fail(e);}}
 static IEnumerator Check(){var probe=Object.FindFirstObjectByType<ReflectionProbe>();int id=probe.RenderProbe();for(int i=0;i<100&&!probe.IsFinishedRendering(id);i++)yield return null;cam.enabled=false;Shot("01_AllThree_PipelineBias_Unbounded");
 foreach(var r in parts.Where(r=>r!=core))r.enabled=false;core.sharedMaterial.SetFloat("_TransmissionDebug",7);Shot("02_GPU_PipelineBias_EncodedAbsTimes2");var value=pixels.GetPixel(640,450);File.WriteAllText(Out+"/gpu-shadow-bias.txt",$"Encoded GPU sample linearRGBA={value}; abs raw depth={value.r/2:F6}m; abs raw normal={value.g/2:F6}m; depthNegative={value.b>.5f}; quantization±0.000981m. Both signs in URP ShadowUtils derive from negative bias times texelSize. Does not measure submillimetre cap error.\n");core.sharedMaterial.SetFloat("_TransmissionDebug",0);foreach(var r in parts)r.enabled=true;
 foreach(var r in parts)r.sharedMaterial.SetVector("_CasterBiasLimit",new Vector4(.00075f,.0005f,0,0));yield return null;Shot("03_AllThree_SignedBiasCaps_075_05mm");cam.transform.position=item.transform.TransformPoint(new Vector3(-.10f,.335f,-.15f));cam.transform.LookAt(item.transform.TransformPoint(new Vector3(0,.315f,0)));Shot("04_ActualHoleCopperTermination_Y315mm");
 var optics=QingGuiR03FirstLook.VerifyOpticsOnly(cam,item,RenderSettings.sun,probe,Out);while(optics.MoveNext())yield return optics.Current;File.WriteAllText(Out+"/optics-result.txt","PASS capped caster independent optics; original Mobile receiver/shadowmap and external standard-Lit blocker retained\n");try{var console=QingGuiR03QuickFit.Check(item,Out);Object.Destroy(console);}catch(Exception e){File.WriteAllText(Out+"/separate-quickfit-failure.txt",e.ToString());}File.WriteAllText(Out+"/result.txt","PASS diagnostic capture and optical checks. Visual acceptance and separate geometric positive controls remain distinct.\n");EditorApplication.Exit(0);}
 static void Shot(string name){RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=target});var old=RenderTexture.active;RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,1280,960),0,0);pixels.Apply();RenderTexture.active=old;var gamma=new Texture2D(1280,960,TextureFormat.RGB24,false);gamma.SetPixels(pixels.GetPixels().Select(c=>c.gamma).ToArray());gamma.Apply();File.WriteAllBytes(Out+"/"+name+".png",gamma.EncodeToPNG());Object.Destroy(gamma);}
 static void Step(){try{if(++frame>240)throw new Exception("Caster diagnosis frame bound");if(!routine.MoveNext())EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
 static void Fail(Exception e){QingGuiR03ReviewTick.Tick=null;Directory.CreateDirectory(Out);File.WriteAllText(Out+"/failure.txt",e.ToString());EditorApplication.Exit(3);}
}
